macro_rules! deps {
    () => {
        DFA!();
        ByteClasses!();
    };
}

macro_rules! TransitionTable {
    () => {
        deps!();
        # [doc = " The transition table portion of a dense DFA."] # [doc = ""] # [doc = " The transition table is the core part of the DFA in that it describes how"] # [doc = " to move from one state to another based on the input sequence observed."] # [derive (Clone)] pub (crate) struct TransitionTable < T > { # [doc = " A contiguous region of memory representing the transition table in"] # [doc = " row-major order. The representation is dense. That is, every state"] # [doc = " has precisely the same number of transitions. The maximum number of"] # [doc = " transitions per state is 257 (256 for each possible byte value, plus 1"] # [doc = " for the special EOI transition). If a DFA has been instructed to use"] # [doc = " byte classes (the default), then the number of transitions is usually"] # [doc = " substantially fewer."] # [doc = ""] # [doc = " In practice, T is either `Vec<u32>` or `&[u32]`."] table : T , # [doc = " A set of equivalence classes, where a single equivalence class"] # [doc = " represents a set of bytes that never discriminate between a match"] # [doc = " and a non-match in the DFA. Each equivalence class corresponds to a"] # [doc = " single character in this DFA's alphabet, where the maximum number of"] # [doc = " characters is 257 (each possible value of a byte plus the special"] # [doc = " EOI transition). Consequently, the number of equivalence classes"] # [doc = " corresponds to the number of transitions for each DFA state. Note"] # [doc = " though that the *space* used by each DFA state in the transition table"] # [doc = " may be larger. The total space used by each DFA state is known as the"] # [doc = " stride."] # [doc = ""] # [doc = " The only time the number of equivalence classes is fewer than 257 is if"] # [doc = " the DFA's kind uses byte classes (which is the default). Equivalence"] # [doc = " classes should generally only be disabled when debugging, so that"] # [doc = " the transitions themselves aren't obscured. Disabling them has no"] # [doc = " other benefit, since the equivalence class map is always used while"] # [doc = " searching. In the vast majority of cases, the number of equivalence"] # [doc = " classes is substantially smaller than 257, particularly when large"] # [doc = " Unicode classes aren't used."] classes : ByteClasses , # [doc = " The stride of each DFA state, expressed as a power-of-two exponent."] # [doc = ""] # [doc = " The stride of a DFA corresponds to the total amount of space used by"] # [doc = " each DFA state in the transition table. This may be bigger than the"] # [doc = " size of a DFA's alphabet, since the stride is always the smallest"] # [doc = " power of two greater than or equal to the alphabet size."] # [doc = ""] # [doc = " While this wastes space, this avoids the need for integer division"] # [doc = " to convert between premultiplied state IDs and their corresponding"] # [doc = " indices. Instead, we can use simple bit-shifts."] # [doc = ""] # [doc = " See the docs for the `stride2` method for more details."] # [doc = ""] # [doc = " The minimum `stride2` value is `1` (corresponding to a stride of `2`)"] # [doc = " while the maximum `stride2` value is `9` (corresponding to a stride of"] # [doc = " `512`). The maximum is not `8` since the maximum alphabet size is `257`"] # [doc = " when accounting for the special EOI transition. However, an alphabet"] # [doc = " length of that size is exceptionally rare since the alphabet is shrunk"] # [doc = " into equivalence classes."] stride2 : usize , }
    };
}

TransitionTable!()